(function(){"use strict";var UI=window.ReviewUI,Store=window.ReviewStore;function injectSchema(stats,reviews,profileUrl){if(!stats.total)return;var json={"@context":"https://schema.org","@type":"LodgingBusiness",name:"Sunrise Hostels",image:"https://www.sunrisehostels.org/favicon-512x512.png",url:"https://www.sunrisehostels.org/",address:{"@type":"PostalAddress",streetAddress:"In front of Gurukripa Coaching, Nawalgarh Road",addressLocality:"Sikar",addressRegion:"Rajasthan",addressCountry:"IN",},aggregateRating:{"@type":"AggregateRating",ratingValue:stats.average.toFixed(1),reviewCount:stats.total,bestRating:5,worstRating:1,},review:reviews.slice(0,5).map(function(r){return{"@type":"Review",author:{"@type":"Person",name:r.authorName},reviewRating:{"@type":"Rating",ratingValue:r.rating,bestRating:5,worstRating:1},reviewBody:r.reviewText,datePublished:r.publishTime||undefined,};}),};var el=document.getElementById("gr-schema");if(!el){el=document.createElement("script");el.type="application/ld+json";el.id="gr-schema";document.head.appendChild(el);}
el.textContent=JSON.stringify(json);}
function reveal(container){requestAnimationFrame(function(){container.querySelectorAll(".reveal").forEach(function(n){n.classList.add("in");});});}
function boot(){var section=document.getElementById("google-reviews");if(!section||!UI||!Store)return;var headEl=document.getElementById("gr-header");var cardsEl=document.getElementById("gr-cards");cardsEl.innerHTML=UI.skeleton(5);Promise.all([Store.getStats(),Store.getLatest(5),Store.getProfileUrls()]).then(function(res){var stats=res[0],latest=res[1],urls=res[2];headEl.innerHTML=UI.summary(stats,{tagline:"Trusted by hundreds of students. Read genuine reviews from our residents.",writeUrl:urls.writeReviewUrl,viewAllUrl:"reviews.html",});reveal(headEl);if(!latest.length){cardsEl.innerHTML=UI.empty("Reviews are on the way — check us out on Google.");return;}
cardsEl.innerHTML=UI.grid(latest);UI.wireReadMore(cardsEl);reveal(cardsEl);injectSchema(stats,latest,urls.profileUrl);}).catch(function(err){console.error("[Sunrise Reviews] homepage load failed:",err);headEl.innerHTML=UI.summary({total:0,average:0},{viewAllUrl:"reviews.html"});reveal(headEl);cardsEl.innerHTML=UI.error();});}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",boot);else boot();})();